{
  "name": "@gitterm/discord-bot",
  "version": "0.3.2",
  "description": "Discord bot that runs a coding agent on your repository in a GitTerm sandbox",
  "keywords": [
    "agent",
    "bot",
    "discord",
    "gitterm",
    "opencode"
  ],
  "homepage": "https://gitterm.dev",
  "license": "MIT",
  "author": "Opeyemi Oginni",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/OpeOginni/gitterm.git",
    "directory": "packages/discord-bot"
  },
  "bin": {
    "gitterm-discord-bot": "dist/cli.js"
  },
  "files": [
    "dist",
    "README.md"
  ],
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "rm -rf dist && bun build src/index.ts src/cli.ts --outdir dist --target node --format esm --packages external && tsc -p tsconfig.build.json",
    "prepublishOnly": "bun run check-types && bun run build",
    "check-types": "tsc --noEmit",
    "start:local": "bun --watch src/cli.ts"
  },
  "dependencies": {
    "@gitterm/bot": "^0.4.0",
    "@gitterm/sdk": "^0.17.0",
    "discord.js": "^14.28.1"
  },
  "devDependencies": {
    "@types/bun": "^1.2.6",
    "typescript": "^5.8.2"
  },
  "engines": {
    "node": ">=22.12.0"
  }
}
